    /** Seat i at the top of the hitbox, each further seat 0.7 blocks behind the one before; turned with the mob. */
    @Override
    protected Vec3 getPassengerAttachmentPoint(Entity passenger, EntityDimensions dimensions, float scale) {
        int index = Math.max(0, getPassengers().indexOf(passenger));
        Vec3 seat = new Vec3(0, dimensions.height(), 0);
        if (index > 0) {
            seat = seat.add(0, 0, -0.7 * index * scale);
        }
        return seat.yRot(-getYRot() * Mth.DEG_TO_RAD);
    }

